mapper.select:
SELECT
(SELECT COUNT(*) FROM sale_lead WHERE deleted=0 AND tenant_id=#{tenantId}
    AND status IN (1,2) AND next_follow_time IS NOT NULL
    AND next_follow_time >= #{dayStart} AND next_follow_time < #{dayEnd}
    AND owner_user IN #{u})
+
(SELECT COUNT(*) FROM customer_info WHERE tenant_id=#{tenantId}
    AND customer_type=1 AND next_follow_time IS NOT NULL
    AND next_follow_time >= #{dayStart} AND next_follow_time < #{dayEnd}
    AND owner_user IN #{u})

SELECT COUNT(*) FROM sale_lead
WHERE deleted=0 AND tenant_id=#{tenantId} AND status IN (1,2)
  AND next_follow_time IS NOT NULL
  AND next_follow_time >= #{dayStart} AND next_follow_time < #{dayEnd}
  AND owner_user IN #{u}

SELECT COUNT(*) FROM customer_info
WHERE tenant_id=#{tenantId} AND customer_type=1
  AND (status IS NULL OR status NOT IN (3, 4))
  AND next_follow_time IS NOT NULL
  AND next_follow_time >= #{dayStart} AND next_follow_time < #{dayEnd}
  AND owner_user IN #{u}

SELECT COUNT(DISTINCT customer_id) FROM orders
WHERE status='PAID' AND tenant_id=#{tenantId}
  AND create_time >= #{start} AND create_time < #{end}
  AND customer_id IS NOT NULL
  AND create_by IN #{u}

SELECT
    COUNT(DISTINCT l.id) AS leads,
    COUNT(DISTINCT c.id) AS customers,
    COUNT(DISTINCT CASE WHEN o.id IS NOT NULL THEN c.id END) AS deals
FROM sale_lead l
LEFT JOIN customer_info c ON c.lead_id = l.id AND c.tenant_id=#{tenantId} AND c.customer_type=1
LEFT JOIN orders o ON o.customer_id = c.id AND o.tenant_id=#{tenantId} AND o.status='PAID'
WHERE l.deleted=0 AND l.tenant_id=#{tenantId}
  AND l.create_time >= #{start} AND l.create_time < #{end}
  AND l.owner_user IN #{u}

SELECT username, real_name
FROM sys_user
WHERE deleted = 0
  AND tenant_id = #{tenantId}
  AND username IN #{u}
ORDER BY real_name, username

SELECT
    usr.username AS username,
    usr.real_name AS real_name,
    COALESCE(f.cnt,0) AS today_follow_count,
    COALESCE(o.cnt,0) AS today_order_count,
    0 AS today_call_count
FROM sys_user usr
LEFT JOIN (
    SELECT owner_user AS username, COUNT(*) AS cnt FROM sale_lead
    WHERE deleted=0 AND tenant_id=#{tenantId}
      AND last_follow_time >= #{dayStart} AND last_follow_time < #{dayEnd}
      AND owner_user IN #{u}
    GROUP BY owner_user
    UNION ALL
    SELECT owner_user AS username, COUNT(*) AS cnt FROM customer_info
    WHERE tenant_id=#{tenantId} AND customer_type=1
      AND last_follow_time >= #{dayStart} AND last_follow_time < #{dayEnd}
      AND owner_user IN #{u}
    GROUP BY owner_user
) f ON f.username=usr.username
LEFT JOIN (
    SELECT create_by AS username, COUNT(*) AS cnt FROM orders
    WHERE status='PAID' AND tenant_id=#{tenantId}
      AND create_time >= #{dayStart} AND create_time < #{dayEnd}
      AND create_by IN #{u}
    GROUP BY create_by
) o ON o.username=usr.username
WHERE usr.tenant_id=#{tenantId} AND usr.deleted=0
  AND usr.username IN #{u}
ORDER BY (COALESCE(f.cnt,0)+COALESCE(o.cnt,0)) ASC

SELECT
    COALESCE(SUM(final_amount), 0) AS amount,
    COUNT(*) AS count
FROM orders WHERE status='PENDING' AND tenant_id=#{tenantId}
  AND create_by IN #{u}

SELECT
    COALESCE(SUM(final_amount),0) AS amount,
    COUNT(*) AS count
FROM orders WHERE status IN ('REFUNDED','REFUNDING') AND tenant_id=#{tenantId}
  AND update_time >= #{start} AND update_time < #{end}
  AND create_by IN #{u}

SELECT
    o.create_by AS username,
    MAX(u.real_name) AS real_name,
    COUNT(*) AS order_count,
    COALESCE(SUM(o.final_amount),0) AS order_amount
FROM orders o
LEFT JOIN sys_user u ON u.username=o.create_by AND u.tenant_id=#{tenantId} AND u.deleted=0
WHERE o.status='PAID' AND o.tenant_id=#{tenantId}
  AND o.create_time >= #{start} AND o.create_time < #{end}
  AND o.create_by IN #{u}
GROUP BY o.create_by
ORDER BY order_amount DESC
LIMIT #{limit}

SELECT DATE_FORMAT(create_time, '%Y-%m') AS month,
       COALESCE(SUM(final_amount),0) AS amount,
       COUNT(*) AS order_count
FROM orders
WHERE status='PAID' AND tenant_id=#{tenantId}
  AND create_time >= #{start} AND create_time < #{end}
  AND create_by IN #{u}
GROUP BY month ORDER BY month

SELECT
(SELECT COUNT(*) FROM sale_lead WHERE deleted=0 AND tenant_id=#{tenantId}
    AND create_time >= #{start} AND create_time < #{end}
    AND owner_user IN #{u}) AS leads,
(SELECT COUNT(*) FROM customer_info WHERE tenant_id=#{tenantId} AND customer_type=1
    AND create_time >= #{start} AND create_time < #{end}
    AND owner_user IN #{u}) AS customers,
(SELECT COUNT(DISTINCT customer_id) FROM orders WHERE status='PAID' AND tenant_id=#{tenantId}
    AND create_time >= #{start} AND create_time < #{end}
    AND create_by IN #{u}) AS deals

SELECT COALESCE(SUM(final_amount),0) FROM orders
WHERE status='PAID' AND tenant_id=#{tenantId}
  AND create_time >= #{start} AND create_time < #{end}
  AND create_by IN #{u}

SELECT COUNT(*) FROM orders
WHERE status='PAID' AND tenant_id=#{tenantId}
  AND create_time >= #{start} AND create_time < #{end}
  AND create_by IN #{u}

SELECT
    COALESCE(AVG(final_amount), 0) AS avg_amount,
    COUNT(*) AS order_count
FROM orders WHERE status='PAID' AND tenant_id=#{tenantId}
  AND create_time >= #{start} AND create_time < #{end}
  AND create_by IN #{u}

SELECT
    COALESCE(b.business_name, '其他') AS name,
    COALESCE(SUM(od.amount),0) AS value,
    COUNT(DISTINCT o.id) AS count
FROM orders o
JOIN order_details od ON od.order_id=o.id AND od.tenant_id=#{tenantId}
LEFT JOIN sys_business b ON b.id=od.business_id AND b.deleted=0
WHERE o.status='PAID' AND o.tenant_id=#{tenantId}
  AND o.create_time >= #{start} AND o.create_time < #{end}
  AND o.create_by IN #{u}
GROUP BY b.business_name
ORDER BY value DESC

SELECT
    COALESCE(source, '未知') AS source,
    COUNT(*) AS leads,
    SUM(CASE WHEN status=3 THEN 1 ELSE 0 END) AS converted,
    ROUND(SUM(CASE WHEN status=3 THEN 1 ELSE 0 END)*100.0/NULLIF(COUNT(*),0), 2) AS rate
FROM sale_lead
WHERE deleted=0 AND tenant_id=#{tenantId}
  AND create_time >= #{start} AND create_time < #{end}
  AND owner_user IN #{u}
GROUP BY source ORDER BY rate DESC

SELECT DATE_FORMAT(create_time,'%Y-%m') AS month,
       COALESCE(SUM(final_amount),0) AS amount
FROM orders WHERE status='PAID' AND tenant_id=#{tenantId}
  AND create_by=#{username}
  AND create_time >= #{start} AND create_time < #{end}
GROUP BY month ORDER BY month

SELECT
    COUNT(DISTINCT l.id) AS leads,
    COUNT(DISTINCT c.id) AS customers,
    COUNT(DISTINCT CASE WHEN o.id IS NOT NULL THEN c.id END) AS deals
FROM sale_lead l
LEFT JOIN customer_info c ON c.lead_id = l.id AND c.tenant_id=#{tenantId} AND c.customer_type=1
LEFT JOIN orders o ON o.customer_id = c.id AND o.tenant_id=#{tenantId} AND o.status='PAID'
WHERE l.deleted=0 AND l.tenant_id=#{tenantId}
  AND l.owner_user=#{username}
  AND l.create_time >= #{start} AND l.create_time < #{end}

SELECT day, SUM(cnt) AS count FROM (
  SELECT DATE(last_follow_time) AS day, COUNT(*) AS cnt FROM sale_lead
  WHERE deleted=0 AND tenant_id=#{tenantId} AND owner_user=#{username}
    AND last_follow_time >= #{from}
  GROUP BY DATE(last_follow_time)
  UNION ALL
  SELECT DATE(last_follow_time) AS day, COUNT(*) AS cnt FROM customer_info
  WHERE tenant_id=#{tenantId} AND customer_type=1 AND owner_user=#{username}
    AND last_follow_time >= #{from}
  GROUP BY DATE(last_follow_time)
) t
WHERE day IS NOT NULL
GROUP BY day ORDER BY day
